TITLE="trellis prep/post scan kernels: avx512icl vs avx2"
BRANCHES="wip/x264-nw-trprep"
BASE=2534f770880f5214a8dada28c37ef79452918182
ARM=2534f770880f5214a8dada28c37ef79452918182
ARMDESC="2534f770 with quant_4x4x4_scan_trellis / quant_8x8_scan_trellis / dequant_4x4x4_scan(_ac) = *_avx512icl"
DEF_MODES="normal"
DEF_NULLCELLS="tile-chaos-p:lowlat field-frame-mix-i:lowlat"   # md5 still covers every clip x lowlat normal
LIVE_CELLS=${LIVE_CELLS:-"tile-chaos-p:normal field-frame-mix-i:normal"}
LIVE_SHOW='scan_trellis|dequant_4x4x4_scan|trellis'
LIVE_ASSERT=${LIVE_ASSERT:-'A+:scan_trellis_(frame|field)_avx512icl B0:scan_trellis_(frame|field)_avx512icl B+:scan_trellis_(frame|field)_avx2 A0:scan_trellis_(frame|field)_avx2'}
