patch_arm() { # the anchor is the 8-bit (#else of HIGH_BIT_DEPTH) icl quant_8x8_scan line, unique in the file
    want common/dct.c 'pf_progressive->quant_8x8_scan = b_cqm_flat ? x264_quant_8x8_scan_frame_flat_avx512icl : x264_quant_8x8_scan_frame_avx512icl;' 1 &&
    pl common/dct.c 's|(        pf_progressive->quant_8x8_scan = b_cqm_flat \? x264_quant_8x8_scan_frame_flat_avx512icl : x264_quant_8x8_scan_frame_avx512icl;\n)|$1        pf_interlaced->quant_4x4x4_scan_trellis  = x264_quant_4x4x4_scan_trellis_field_avx512icl;\n        pf_progressive->quant_4x4x4_scan_trellis = x264_quant_4x4x4_scan_trellis_frame_avx512icl;\n        pf_interlaced->quant_8x8_scan_trellis    = x264_quant_8x8_scan_trellis_field_avx512icl;\n        pf_progressive->quant_8x8_scan_trellis   = x264_quant_8x8_scan_trellis_frame_avx512icl;\n        pf_interlaced->dequant_4x4x4_scan        = x264_dequant_4x4x4_scan_field_avx512icl;\n        pf_progressive->dequant_4x4x4_scan       = x264_dequant_4x4x4_scan_frame_avx512icl;\n        pf_interlaced->dequant_4x4x4_scan_ac     = x264_dequant_4x4x4_scan_field_ac_avx512icl;\n        pf_progressive->dequant_4x4x4_scan_ac    = x264_dequant_4x4x4_scan_frame_ac_avx512icl;\n|' &&
    want common/dct.c 'pf_progressive->quant_4x4x4_scan_trellis = x264_quant_4x4x4_scan_trellis_frame_avx512icl;' 1
}

# ===========================================================================================
# rack01 in-situ A/B engine for x264-obe (Zen 4, EPYC 8324P). Copyright (C) 2026 Open Broadcast Systems Ltd
# This block is generated into every rack01-jobs/<pkg>/<job>.sh by rack01-jobs/lib/mkjobs.sh from
# rack01-jobs/lib/engine.sh. Edit engine.sh or the job's .conf, then rerun mkjobs.sh.
#
#   bash <job>.sh all              preflight build check live md5 time report clean (stops at a failed gate)
#   bash <job>.sh preflight        CORE, nasm, decoders stopped, clips, disk
#   bash <job>.sh build            git-archive trees base / base2 / arm / arm2 (arm patch asserted), x264 + checkasm
#   bash <job>.sh check            checkasm seeds 1001 2002 3003 in base and arm
#   bash <job>.sh bench            checkasm --bench rows of $BENCH in the arm tree (3 seeds)
#   bash <job>.sh live             perf record samples, base and arm: the arm runs the new code, null cells run none
#   bash <job>.sh md5              gate: recon md5 across the 4 arms, bitstream md5 within one sha (timing cells,
#                                  MD5CLIPS x MD5MODES, the 8-bit 4:2:2 interlaced cells MD5X, EXTRA_MD5)
#   bash <job>.sh time [R]         R rounds (default 12), arm order rotated, resumable; stops at round 6 on a clear result
#   bash <job>.sh report           per-cell paired medians of cycles:u, A/A, instructions:u, verdict
#   bash <job>.sh mbm [reps]       resctrl MBM L3<->DRAM bytes per frame, base vs arm (NEEDS KIERAN ROOT: setup-cmds)
#   bash <job>.sh setup-cmds       prints the root commands for mbm (never runs them)
#   bash <job>.sh clean            copies the step outputs to $RES, removes $W (trees, clips, outputs)
#   bash <job>.sh patchcheck       archive + patch only, no build (dry check of the arm patch)
#   bash <job>.sh <step>           a package step: pkgstep_<step> in the job's .conf (e.g. mvpredc's twin gate)
# Env: CORE (required: one idle cpu, e.g. a node-3 cpu), CLIPS (default ~/x264-parity/clips), W, SRC (shared
#      clone, kept), RES, ROUNDS (12), FRAMES (0 = whole clips), GENFRAMES (150: generated 4:2:2 clips),
#      CLIPLIST / MODES / NULLCELLS / MD5X to override the job's cells. AB / BITDEPTH pick the arm pair / build depth
#      where the .conf offers several ($JOB, $W and $RES then carry them).
# Timing: taskset -c $CORE perf stat -x, -e cycles:u,instructions:u -- x264 ... (perf pinned with x264).
# Rules: decoders stopped (SNMP) before timing, nothing else heavy on the box, --threads 1.
# ===========================================================================================
set -u
export LC_ALL=C
export PATH=/usr/local/bin:$PATH            # rack01: nasm 3.02 (/usr/bin/nasm 2.14 miscompiles %assign a == b)
W=${W:-$HOME/r01-$JOB}
CLIPS=${CLIPS:-$HOME/x264-parity/clips}
CORE=${CORE:-}
REPO=${REPO:-https://github.com/kierank/x264-obe}
SRC=${SRC:-$HOME/x264-r01-src}
RES=${RES:-$HOME/r01-results/$JOB}
ROUNDS=${ROUNDS:-12}
FRAMES=${FRAMES:-0}
GENFRAMES=${GENFRAMES:-150}
BD=${BITDEPTH:-8}
CLIPLIST=${CLIPLIST:-${DEF_CLIPLIST:-fades-p tile-chaos-p pan-fast-p fades-i field-frame-mix-i credits-i}}
MODES=${MODES:-${DEF_MODES:-lowlat normal}}
NULLCELLS=${NULLCELLS-${DEF_NULLCELLS:-}}
MD5X=${MD5X-${DEF_MD5X-fades-i-422 field-frame-mix-i-422 credits-i-422}}
MD5XMODES=${MD5XMODES:-lowlat normal}
MD5CLIPS=${MD5CLIPS:-$CLIPLIST}          # the md5 gate covers MD5CLIPS x MD5MODES even where the timing runs fewer modes
MD5MODES=${MD5MODES:-lowlat normal}
EXTRA_MD5=${EXTRA_MD5:-}
LIVE_CELLS=${LIVE_CELLS:-tile-chaos-p:normal field-frame-mix-i:lowlat}
LIVE_ASSERT=${LIVE_ASSERT:-}
LIVE_SHOW=${LIVE_SHOW:-.}
NULL_ASSERT=${NULL_ASSERT:-}
NODUMP_GATE=${NODUMP_GATE:-0}
BENCH=${BENCH:-}
BENCH_GREP=${BENCH_GREP:-.}
BASE_XCFLAGS=${BASE_XCFLAGS:-}
ARM_XCFLAGS=${ARM_XCFLAGS:-}
ALLSTEPS=${ALLSTEPS:-preflight build check live md5 time report clean}
PERIOD=${PERIOD:-200003}
STRESSGEN_SHA=cf6070519e18a9aee66e2c29b7518e957ed54a43   # test/stressgen tools/stressgen.c (rack01's harness copy)
ARMS="base base2 arm arm2"
BUILD_TREES=${BUILD_TREES:-$ARMS}

die() { echo "FATAL: $*" >&2; exit 1; }
declare -F patch_base > /dev/null || patch_base() { :; }
declare -F patch_arm  > /dev/null || patch_arm()  { :; }
declare -F pkg_mode   > /dev/null || pkg_mode()   { return 1; }

# ---- patch helpers (run inside the tree) ----
pl() { # file perl-substitution (whole file): must change the file; prints the changed lines
    local f=$1; shift
    cp "$f" "$f.orig" || return 1
    perl -0777 -pi -e "$1" "$f" || { echo "PATCH ERROR: $f"; return 1; }
    cmp -s "$f" "$f.orig" && { echo "PATCH DID NOT APPLY: $f: $1"; return 1; }
    diff "$f.orig" "$f" | grep '^[<>]' | sed "s|^|    $f: |"; rm -f "$f.orig"
}
want() { # file fixed-string count: the assertion grep of a patch
    local n; n=$(grep -cF -- "$2" "$1")
    [ "$n" = "$3" ] || { echo "ASSERT FAILED: $1 has $n x '$2', want $3"; return 1; }
    echo "    assert ok: $1 has $3 x '$2'"
}
before() { # file string1 string2: the first line with string1 comes before the first with string2
    local a b; a=$(grep -nF -- "$2" "$1" | head -1 | cut -d: -f1); b=$(grep -nF -- "$3" "$1" | head -1 | cut -d: -f1)
    [ -n "$a" ] && [ -n "$b" ] && [ "$a" -lt "$b" ] || { echo "ASSERT FAILED: $1: '$2' (line $a) not before '$3' (line $b)"; return 1; }
    echo "    assert ok: $1: '$2' (line $a) before '$3' (line $b)"
}

# ---- clips and cells ----
llopts() { echo "--preset veryfast --tune zerolatency --intra-refresh --vbv-bufsize $(($1/30))"; }   # lowlat at bitrate $1
nmopts() { echo "--subme 6 --me hex --ref 2 --no-mixed-refs --no-chroma-me --trellis 1 --partitions i8x8,i4x4 --psy-rd 1.0:0 --bframes 3 --rc-lookahead 24 --vbv-bufsize $1"; }   # production P6 normal
is422() { case $1 in *-422|*-422p10) return 0;; esac; return 1; }
clipfile() { if is422 $1; then echo $W/clips/$1.y4m; else echo $CLIPS/$1.y4m; fi; }
encopts() { # clip mode -> x264 options (production P6 normal, lowlat = veryfast + zerolatency + PIR)
    local c=$1 m=$2 br=20000 prof="--profile high" csp="" il="" o fr=""
    is422 $c && { br=50000; prof="--profile high422"; csp="--output-csp i422"; }
    case $c in *-i|*-i-422|*-i-422p10) il="--tff";; esac
    [ "$FRAMES" != 0 ] && fr="--frames $FRAMES"
    local ll nm; ll=$(llopts $br); nm=$(nmopts $br)
    case $m in
    lowlat)        o=$ll;;
    normal)        o=$nm;;
    lowlat_dia)    o="$ll --me dia";;                  # the fused fpel search makes zero calls
    dia)           o="--preset superfast --tune zerolatency --intra-refresh --vbv-bufsize $((br/30)) --me dia --subme 1";;   # speedcontrol presets 0-1 (overload)
    medium)        o="--ref 4 --bframes 3 --rc-lookahead 24 --vbv-bufsize $br";;   # plain medium = rack01 "n" cells, NOT production
    normal_no8x8dct) o="$nm --no-8x8dct";;
    normal_nowp)   o="$nm --weightp 0";;
    *) o=$(pkg_mode $m $br) || { echo "unknown mode $m" >&2; return 1; };;
    esac
    echo "--bitrate $br --vbv-maxrate $br --nal-hrd fakevbr --aud --pic-struct --open-gop $prof $csp --keyint 30 --threads 1 --no-progress $il $fr $o"
}
isnull() { # cell -> 0 if it is a null control (NULLCELLS entries are cells or globs like *:lowlat)
    local p; for p in $NULLCELLS; do [[ $1 == $p ]] && return 0; done; return 1
}
cells_time() { # CLIPLIST x MODES, plus the explicit (non-glob) null cells
    { for c in $CLIPLIST; do for m in $MODES; do echo $c:$m; done; done
      for p in $NULLCELLS; do case $p in *'*'*) ;; *) echo $p;; esac; done; } | awk '!s[$0]++'
}
cells_md5() {
    { cells_time; for c in $MD5CLIPS; do for m in $MD5MODES; do echo $c:$m; done; done
      for c in $MD5X; do for m in $MD5XMODES; do echo $c:$m; done; done; for x in $EXTRA_MD5; do echo $x; done; } | awk '!s[$0]++'
}
nullcells() { for x in $(cells_time) $(cells_md5); do isnull $x && echo $x; done | awk '!s[$0]++'; }
genclips() { # 4:2:2 clips (8-bit -422, 10-bit -422p10) generated with stressgen, GENFRAMES frames each
    local need c s fps il dep f
    need=$( { cells_md5; for x in $LIVE_CELLS; do echo $x; done; } | cut -d: -f1 | awk '!s[$0]++')
    for c in $need; do is422 $c || continue
        f=$W/clips/$c.y4m; [ -s $f ] && continue
        mkdir -p $W/clips
        if [ ! -x $W/stressgen ]; then
            git -C $SRC show $STRESSGEN_SHA:tools/stressgen.c > $W/stressgen.c || die "stressgen source"
            gcc -O3 -o $W/stressgen $W/stressgen.c -lm || die "stressgen build"
        fi
        s=${c%-422*}; dep=8; case $c in *p10) dep=10;; esac
        case $s in *-i) fps=30000/1001; il=tff;; *) fps=60000/1001; il=none;; esac
        s=${s%-?}
        taskset -c $CORE $W/stressgen --scenario $s --fps $fps --interlaced $il --csp 422 --depth $dep --frames $GENFRAMES > $f || die "stressgen $c"
        echo "generated $c: stressgen --scenario $s --fps $fps --interlaced $il --csp 422 --depth $dep --frames $GENFRAMES ($(md5sum < $f | cut -c1-32))"
    done
}

# ---- trees ----
fetchsrc() {
    if [ -z "${NOFETCH:-}" ]; then
        [ -d $SRC/.git ] || [ -f $SRC/HEAD ] || git clone -q --no-checkout $REPO $SRC || die "clone $REPO"
        local b; for b in $BRANCHES test/stressgen; do
            git -C $SRC fetch -q origin "+refs/heads/$b:refs/remotes/origin/$b" || die "fetch $b (network? retry)"
        done
    fi
    local s; for s in $BASE $ARM $STRESSGEN_SHA; do git -C $SRC cat-file -e "$s^{commit}" 2> /dev/null || die "$s is not in $SRC"; done
}
tree() { # name sha patchfn [nobuild]
    local d=$W/$1 xc=$BASE_XCFLAGS
    case $1 in arm*) xc=$ARM_XCFLAGS;; esac
    [ -x $d/x264 ] && return 0
    rm -rf $d && mkdir -p $d || die "mkdir $d"
    git -C $SRC -c core.autocrlf=false archive $2 | tar -x -C $d || die "archive $2"
    echo "$1 $2" > $d/SHA
    echo "== $1: $2 $(git -C $SRC log -1 --format=%s $2)"
    (cd $d && $3) || die "$3 failed in $1"
    [ "${4:-}" = nobuild ] && return 0
    (cd $d && ./configure --bit-depth=$BD --enable-static --disable-opencl --disable-lavf --disable-ffms --disable-gpac \
        --disable-lsmash --disable-swscale --extra-cflags="-fno-fast-math -ffp-contract=off -fno-pie $xc" \
        --extra-ldflags="-no-pie" > cfg.log 2>&1) || { tail -5 $d/cfg.log; die "configure $1"; }
    (cd $d && make -j"$(nproc)" x264 checkasm$BD > make.log 2>&1) || { tail -20 $d/make.log; die "make $1"; }
}

# ---- one encode: prints "cycles instructions" ----
enc() { # tree clip mode tag [dump|bs]
    local a=$1 c=$2 m=$3 t=$4 o out=/dev/null dump=""
    o=$(encopts $c $m) || return 1
    case ${5:-} in dump) out=$W/out/$t.264; dump="--dump-yuv $W/out/$t.yuv";; bs) out=$W/out/$t.264;; esac
    taskset -c $CORE perf stat -x, -e cycles:u,instructions:u -o $W/out/$t.perf -- \
        $W/$a/x264 $o $dump -o $out $(clipfile $c) 2> $W/out/$t.log < /dev/null
    local rc=$?
    [ $rc = 0 ] || { echo "ENCODE FAILED (rc $rc): $a $c $m, log $W/out/$t.log" >&2; tail -3 $W/out/$t.log >&2; return 1; }
    awk -F, '$3 ~ /^cycles:u/ { c = $1 } $3 ~ /^instructions:u/ { i = $1 } END { print c + 0, i + 0 }' $W/out/$t.perf
}
livesyms() { # perf.data -> "samples symbol" lines, every user symbol
    perf report -i $1 -q -n --stdio --sort sym 2> /dev/null | awk '/\[\.\]/ { print $2, $NF }'
}
showsyms() { # syms file -> the 6 biggest symbols matching LIVE_SHOW
    awk -v re="$LIVE_SHOW" '$2 ~ re' $1 | sort -rn | head -6 | awk '{ printf "%s %s; ", $2, $1 }'
}
assert_live() { # base-syms arm-syms asserts -> PASS/FAIL lines; tokens A+:re A0:re B+:re B0:re A<B:re A>B:re (anything else = info)
    local bf=$1 af=$2 t k re nb na ok=0
    for t in $3; do k=${t%%:*}; re=${t#*:}
        nb=$(awk -v re="$re" '$2 ~ re { s += $1 } END { print s + 0 }' $bf); na=$(awk -v re="$re" '$2 ~ re { s += $1 } END { print s + 0 }' $af)
        case $k in
        A+) [ $na -gt 0 ];; A0) [ $na = 0 ];; B+) [ $nb -gt 0 ];; B0) [ $nb = 0 ];; 'A<B') [ $na -lt $nb ];; 'A>B') [ $na -gt $nb ];; *) true;;
        esac && echo "    LIVE ok   $k /$re/ base $nb arm $na samples" || { echo "    LIVE FAIL $k /$re/ base $nb arm $na samples"; ok=1; }
    done
    return $ok
}

# ---- timing analysis (times.txt: round cell arm cycles instructions) ----
analyse() { # N mode(stop|final): per-cell medians over rounds <= N, prints the status line last
    awk -v N=$1 -v MODE=$2 -v NULLS="$(nullcells | tr '\n' ' ')" '
    function med( v, n,   i, j, x ) { for( i = 1; i <= n; i++ ) for( j = i+1; j <= n; j++ ) if( v[j] < v[i] ) { x = v[i]; v[i] = v[j]; v[j] = x }
                                    return n % 2 ? v[(n+1)/2] : (v[n/2] + v[n/2+1]) / 2 }
    $1 <= N { cy[$2" "$1" "$3] = $4; in_[$2" "$3" "$1] = $5; ins[$2" "$1" "$3] = $5; if( !($2 in seen) ) { seen[$2] = 1; order[++nc] = $2 } }
    END {
      split( NULLS, nl, " " ); for( i in nl ) isnull[nl[i]] = 1
      win = 1; loss = 1; fwin = 1; floss = 1; np = 0; nok = 0; sig = 0; hardloss = 0
      for( q = 1; q <= nc; q++ ) { c = order[q]; n = 0; slow = 0; fast = 0
        for( r = 1; r <= N; r++ ) { k = c" "r
          if( !((k" base") in cy && (k" base2") in cy && (k" arm") in cy && (k" arm2") in cy) ) continue
          n++; d[n] = 100*((cy[k" arm"] + cy[k" arm2"]) / (cy[k" base"] + cy[k" base2"]) - 1)
          a1[n] = 100*(cy[k" base2"]/cy[k" base"] - 1); a2[n] = 100*(cy[k" arm2"]/cy[k" arm"] - 1)
          di[n] = 100*((ins[k" arm"] + ins[k" arm2"]) / (ins[k" base"] + ins[k" base2"]) - 1)
          bc[n] = (cy[k" base"] + cy[k" base2"]) / 2e9
          if( d[n] > 0 ) slow++; else if( d[n] < 0 ) fast++ }
        if( n == 0 ) continue
        m = med( d, n ); tag = (c in isnull) ? "NULL" : (c ~ /:medium$/ ? "MEDIUM" : "PROD")
        printf "%-30s %-6s arm-base %+6.2f %%  faster %2d/%-2d  A/A base %+5.2f %% arm %+5.2f %%  instr:u %+6.3f %%  base %.2f Gcyc\n", c, tag, m, fast, n, med(a1,n), med(a2,n), med(di,n), med(bc,n)
        if( tag == "NULL" ) continue
        np++
        if( !(n >= 6 && slow >= 5*n/6 && m > 0.3) ) loss = 0
        aa = med(a1,n); ab = med(a2,n); if( aa < 0 ) aa = -aa; if( ab < 0 ) ab = -ab; if( ab > aa ) aa = ab
        pflag = (med(di,n) <= 0.01 && med(di,n) >= -0.01 && (m > 0.2 || m < -0.2))   # instructions flat, cycles moved: placement
        if( m < 0 && fast >= 4*n/6 ) nok++
        if( m < -aa && fast >= 5*n/6 ) sig = 1
        if( !pflag && m > aa && fast <= n/6 ) hardloss = 1
        if( !(m < 0 && fast >= 0.75*n) ) fwin = 0
        if( !(m > 0 && slow >= 0.75*n) ) floss = 0
      }
      if( np == 0 ) { print "STATUS NO-DECISION-CELLS"; exit }
      # Kieran 11-13: a test that wins clearly after six rounds stops there. Clear win = no real loss
      # (no non-placement cell slower beyond its A/A with <= 1/6 faster), >= 2/3 of cells faster (median < 0, >= 4/6),
      # and at least one cell faster beyond its A/A in >= 5/6
      win = (N >= 6 && !hardloss && nok >= 2*np/3 && sig)
      if( MODE == "stop" ) print (win ? "STATUS STOP-WIN (clear win: no real loss, >= 2/3 of cells faster, one beyond its A/A)" : loss ? "STATUS STOP-LOSS (slower in >= 5/6 rounds and > +0.3 % on every decision cell)" : "STATUS CONTINUE")
      else print (fwin ? "STATUS WIN (median faster and faster in >= 75 % of rounds on every decision cell)" : floss ? "STATUS LOSS (median slower and slower in >= 75 % of rounds on every decision cell)" : "STATUS MIXED/NEUTRAL (judge per cell against the A/A rows)")
    }' $W/times.txt
}

# ---- MBM (resctrl) ----
RESCTRL=/sys/fs/resctrl
MG=$RESCTRL/x264ab/mon_groups/e0
mbmbytes() { cat $MG/mon_data/mon_L3_*/mbm_total_bytes 2> /dev/null | awk '{ s += $1 } END { printf "%.0f\n", s }'; }

step() {
case "${1:-}" in patchcheck|setup-cmds|clean|report|"") ;; *) [ -n "$CORE" ] || die "set CORE to one idle cpu (e.g. a node-3 cpu: numactl -H)";; esac
case "${1:-}" in
patchcheck)
    NOFETCH=${NOFETCH:-1}; fetchsrc; mkdir -p $W
    tree base $BASE patch_base nobuild; tree arm $ARM patch_arm nobuild
    echo "patchcheck $JOB: base and arm trees patched in $W (not built)"
    ;;
preflight)
    [ -n "$CORE" ] || die "set CORE to one idle cpu (e.g. a node-3 cpu: numactl -H)"
    echo "== $JOB on $(hostname), cpu $CORE: $(grep -m1 'model name' /proc/cpuinfo | cut -d: -f2), node $(cat /sys/devices/system/cpu/cpu$CORE/topology/physical_package_id 2> /dev/null)/L3 $(cat /sys/devices/system/cpu/cpu$CORE/cache/index3/id 2> /dev/null)"
    echo "   nasm: $(command -v nasm) $(nasm -v 2> /dev/null)"
    systemctl is-active obdd 2> /dev/null | grep -q '^active' && echo "   WARNING: obdd is active: stop the decoders by SNMP before timing" || echo "   obdd: not active"
    echo "   load: $(cat /proc/loadavg)"
    echo "   disk: $(df -h $HOME | tail -1)"
    for x in $(cells_md5) $LIVE_CELLS; do c=${x%%:*}; is422 $c && continue; [ -s $CLIPS/$c.y4m ] || die "missing clip $CLIPS/$c.y4m"; done
    perf stat -x, -e cycles:u -o /dev/null -- true || die "perf stat does not work for this user"
    ;;
build)
    mkdir -p $W/out; fetchsrc
    for a in $BUILD_TREES; do case $a in base*) tree $a $BASE patch_base;; *) tree $a $ARM patch_arm;; esac; done
    [ "$BUILD_TREES" = "$ARMS" ] || { genclips; return 0; }
    for a in $ARMS; do echo "$a $(cut -d' ' -f2 $W/$a/SHA) x264 $(md5sum < $W/$a/x264 | cut -c1-12) $($W/$a/x264 --version | head -1)"; done
    [ "$(md5sum < $W/base/x264)" = "$(md5sum < $W/base2/x264)" ] && [ "$(md5sum < $W/arm/x264)" = "$(md5sum < $W/arm2/x264)" ] \
        && echo "binaries: base == base2, arm == arm2" || echo "NOTE: base/base2 or arm/arm2 binaries differ (non-reproducible build)"
    [ "$(md5sum < $W/base/x264)" = "$(md5sum < $W/arm/x264)" ] && echo "WARNING: base and arm binaries are IDENTICAL: the arm changes nothing"
    genclips
    ;;
check)
    for a in base arm; do for s in 1001 2002 3003; do
        (cd $W/$a && taskset -c $CORE ./checkasm$BD $s > $W/out/ck_${a}_$s.txt 2>&1); rc=$?
        echo "$a checkasm$BD seed $s: rc $rc, $(grep -c FAILED $W/out/ck_${a}_$s.txt) FAILED, $(tail -1 $W/out/ck_${a}_$s.txt)"
        [ $rc = 0 ] || die "checkasm failed ($a seed $s)"
    done; done
    ;;
bench)
    [ -n "$BENCH" ] || { echo "no BENCH for $JOB"; return 0; }
    for s in 1001 2002 3003; do for b in $BENCH; do
        echo "== seed $s --bench=$b"; (cd $W/arm && taskset -c $CORE ./checkasm$BD --bench=$b $s) | grep -E "$BENCH_GREP"
    done; done
    ;;
live)
    mkdir -p $W/out; rc=0
    for x in $LIVE_CELLS; do c=${x%%:*}; m=${x#*:}
        for a in base arm; do o=$(encopts $c $m) || exit 1
            taskset -c $CORE perf record -q -c $PERIOD -e cycles:u -o $W/out/live_$a.data -- $W/$a/x264 $o -o /dev/null $(clipfile $c) 2> /dev/null < /dev/null || die "perf record $a $x"
            livesyms $W/out/live_$a.data > $W/out/live_${a}_${c}_$m.syms
        done
        echo "$x: base: $(showsyms $W/out/live_base_${c}_$m.syms)"
        echo "$x: arm:  $(showsyms $W/out/live_arm_${c}_$m.syms)"
        [ -n "$LIVE_ASSERT" ] && { assert_live $W/out/live_base_${c}_$m.syms $W/out/live_arm_${c}_$m.syms "$LIVE_ASSERT" || rc=1; }
    done
    for x in $(nullcells | head -${NULL_LIVE_N:-2}); do c=${x%%:*}; m=${x#*:}
        [ -n "$NULL_ASSERT" ] || break
        for a in base arm; do o=$(encopts $c $m) || exit 1
            taskset -c $CORE perf record -q -c $PERIOD -e cycles:u -o $W/out/live_$a.data -- $W/$a/x264 $o -o /dev/null $(clipfile $c) 2> /dev/null < /dev/null || die "perf record $a $x"
            livesyms $W/out/live_$a.data > $W/out/null_${a}_${c}_$m.syms
        done
        echo "$x (null control):"; assert_live $W/out/null_base_${c}_$m.syms $W/out/null_arm_${c}_$m.syms "$NULL_ASSERT" || rc=1
    done
    rm -f $W/out/live_*.data
    [ $rc = 0 ] && echo "LIVE PASS" || { echo "LIVE FAIL (or NOT LIVE: the arm's code is not reached in these cells, or a null control runs it)"; return 1; }
    ;;
md5)
    mkdir -p $W/out; rc=0
    for x in $(cells_md5); do c=${x%%:*}; m=${x#*:}; r=""; b=""
        for a in $ARMS; do
            t=md5_${a}_${c}_$m; enc $a $c $m $t dump > /dev/null || { rc=1; continue 2; }   # per-cell tag: a failed cell keeps its log
            r="$r $(md5sum < $W/out/$t.yuv | cut -c1-32)"; b="$b $(md5sum < $W/out/$t.264 | cut -c1-32)"; rm -f $W/out/$t.yuv
        done
        set -- $b; rd=$(echo $r | tr ' ' '\n' | sort -u | wc -l)
        bb=$(printf "%s\n%s\n" $1 $2 | sort -u | wc -l); ba=$(printf "%s\n%s\n" $3 $4 | sort -u | wc -l); bx=$(printf "%s\n" $b | sort -u | wc -l)
        v=PASS; [ $rd = 1 ] && [ $bb = 1 ] && [ $ba = 1 ] || { v=FAIL; rc=1; }
        line="$x: recon distinct across 4 arms $rd; bitstream distinct base/base2 $bb, arm/arm2 $ba (info: across arms $bx)"
        if [ "$NODUMP_GATE" = 1 ]; then b=""
            for a in $ARMS; do t=nd_${a}_${c}_$m; enc $a $c $m $t bs > /dev/null || { rc=1; continue 2; }; b="$b $(md5sum < $W/out/$t.264 | cut -c1-32)"; done
            nd=$(printf "%s\n" $b | sort -u | wc -l); [ $nd = 1 ] || { v=FAIL; rc=1; }
            line="$line; no-dump bitstream distinct across 4 arms $nd (the gate: archive trees share one version string)"
        fi
        echo "$v $line"
    done
    rm -f $W/out/md5_*.264 $W/out/nd_*.264
    [ $rc = 0 ] && echo "MD5 GATE PASS" || { echo "MD5 GATE FAIL: no timing"; return 1; }
    ;;
time)
    R=${2:-$ROUNDS}; mkdir -p $W/out; touch $W/times.txt; arms=($ARMS)
    r0=$(awk 'END { print $1 + 0 }' $W/times.txt)
    for r in $(seq $((r0 + 1)) $R); do
        for x in $(cells_time); do c=${x%%:*}; m=${x#*:}
            for k in 0 1 2 3; do a=${arms[$(( (k + r) % 4 ))]}
                v=$(enc $a $c $m t) || die "encode failed in round $r"
                echo "$r $x $a $v" >> $W/times.txt
            done
        done
        echo "round $r done $(date -u +%FT%TZ)"
        if [ $r = 6 ]; then analyse 6 stop | tee $W/round6.txt
            grep -q 'STATUS STOP-' $W/round6.txt && { echo "early stop at round 6"; break; }
        fi
    done
    ;;
report)
    n=$(awk 'END { print $1 + 0 }' $W/times.txt)
    echo "== $JOB: $TITLE"; echo "   base $BASE, arm $ARM ($ARMDESC); $n rounds; decision cells: PROD (and MEDIUM if any); NULL = zero-call control"
    [ -n "${ZEN5:-}" ] && echo "   ZEN5 (any failed avx512 is parked, never dropped): on LOSS or MIXED/NEUTRAL against the AVX-512 kernel, the lead creates: $ZEN5"
    analyse $n final
    ;;
setup-cmds)
    echo "# rack01, as root (Kieran), once per boot: one resctrl monitoring group writable by $(id -un)"
    echo "mountpoint -q $RESCTRL || mount -t resctrl resctrl $RESCTRL"
    echo "mkdir -p $RESCTRL/x264ab/mon_groups/e0"
    echo "chown -R $(id -un) $RESCTRL/x264ab"
    echo "# E-2400 L3 share (CAT): rack01-jobs/bwledger/rack01-catmbm.sh setup-cmds on wip/x264-nw-bwledger"
    ;;
mbm)
    [ -w $MG/tasks ] || { echo "NEEDS KIERAN ROOT: resctrl group $MG is not writable. Root commands:"; step setup-cmds; return 2; }
    reps=${2:-3}; mkdir -p $W/out; : > $W/mbm.txt
    for x in $(cells_time); do isnull $x && continue; c=${x%%:*}; m=${x#*:}; o=$(encopts $c $m) || exit 1
        for rep in $(seq 1 $reps); do for a in base arm; do
            b0=$(mbmbytes)
            (echo $BASHPID > $MG/tasks && exec taskset -c $CORE $W/$a/x264 $o -o /dev/null $(clipfile $c) 2> $W/out/mbm.log < /dev/null) || die "mbm encode $a $x"
            b1=$(mbmbytes); f=$(grep -o 'encoded [0-9]* frames' $W/out/mbm.log | awk '{ print $2 }')
            echo "$x $a $rep $((b1 - b0)) $f" | tee -a $W/mbm.txt
        done; done
    done
    awk '{ v[$1" "$2] = v[$1" "$2] " " ($4 / $5 / 1e6); c[$1] = 1 }
    function med( s,   a, n, i, j, x ) { n = split( s, a, " " ); for( i = 1; i <= n; i++ ) for( j = i+1; j <= n; j++ ) if( a[j] < a[i] ) { x = a[i]; a[i] = a[j]; a[j] = x }
                                          return n % 2 ? a[(n+1)/2] : (a[n/2] + a[n/2+1]) / 2 }
    END { for( k in c ) { b = med( v[k" base"] ); a = med( v[k" arm"] ); printf "%-30s L3<->DRAM MB/f base %.2f arm %.2f (%+.2f MB/f, %+.1f %%)\n", k, b, a, a - b, 100*(a/b - 1) } }' $W/mbm.txt | sort
    ;;
clean)
    mkdir -p $RES; cp -p $W/*.txt $RES/ 2> /dev/null; cp -p $W/out/ck_*.txt $RES/ 2> /dev/null
    rm -rf $W; echo "results in $RES; removed $W (the shared clone $SRC is kept)"
    ;;
all)
    mkdir -p $W
    for s in $ALLSTEPS; do
        echo "######## $JOB: $s $(date -u +%FT%TZ)"
        case $s in clean) step clean; continue;; esac
        step $s 2>&1 | tee $W/$s.txt; rc=${PIPESTATUS[0]}
        if [ $rc != 0 ]; then
            echo "######## $JOB: $s failed (rc $rc): stopping"
            [ "${KEEP:-0}" = 1 ] && echo "KEEP=1: trees kept in $W; 'bash $0 clean' removes them" || step clean
            return $rc
        fi
    done
    ;;
*)
    declare -F "pkgstep_${1:-}" > /dev/null && { "pkgstep_$1" "$@"; return; }
    sed -n '/^#   bash <job>.sh all/,/^# Env:/p' $0; return 1
    ;;
esac
}
step "$@"
